import jsPDF from './jspdf';
function getFont(){
  return ``;
}

const getBaseBakimFormu = () => { 
  return `data:image/jpeg;base64,`
}

const getBaseArizaFormu = () => { 
  return `data:image/jpeg;base64,`
}



function generatePdfBakim(obj:{
  birlikAdi,
  sistemAdi,
  subSistemAdi,
  kontrolNo,
  baslangicTarihi,
  baslangicSaati,
  bitisTarihi,
  bitisSaati,
  periyod,
  malzemeler,
  dokuman,
  aciklama,
  personel,
  personelYedek,
  yonetici,
  personelKase,
  personelYedekKase,
  yoneticiKase,
  kalite,
  kaliteKase
}, com){
  var doc = new jsPDF('l');
  var PTSans = getFont();
  var base64=  getBaseBakimFormu();
  doc.addFileToVFS("PTSans.ttf", PTSans);
  doc.addFont('PTSans.ttf', 'PTSans', 'normal');
  doc.addFont('PTSans.ttf', 'PTSans', 'bold');
  var ttt2:any = JSON.stringify(doc.getFontList());
  ttt2 = ttt2.replace('{','');
  ttt2 = ttt2.replace('}','');
  ttt2 = ttt2.split('],');
  doc.setFont('PTSans');
  doc.addImage(base64,'JPEG',0,0,297,210);
  doc.setFontSize(10);
  doc.setFontType("normal");

  doc.text(obj.birlikAdi || '', 34, 35);
  doc.text(((obj.sistemAdi || '') + '-' + (obj.subSistemAdi || '')) || '', 122, 35);
  doc.text(obj.kontrolNo || '', 232, 35);

  doc.text(obj.baslangicTarihi +( obj.baslangicSaati ? " / "+ obj.baslangicSaati : "" ), 60, 55);
  doc.text(obj.bitisTarihi +( obj.bitisSaati ? " / "+ obj.bitisSaati : "" ), 160, 55);
  doc.text(obj.periyod || '', 250, 55);

  obj.malzemeler.forEach((malzeme,index) => {
    doc.text(malzeme.seriNo || '', 10, 77 + ( index * 6));
    doc.text(malzeme.name || '', 41, 77 + ( index * 6));
    doc.text(malzeme.stokNo || '', 96, 77 + ( index * 6));
    doc.text(malzeme.parcaNo || '', 134, 77 + ( index * 6));
    doc.text(malzeme.girilenMiktar || '', 174, 77 + ( index * 6));
    doc.text(malzeme.sarfYeri || '', 196, 77 + ( index * 6));
    doc.text(malzeme.tedarikYeri || '', 234, 77 + ( index * 6));
    doc.text(malzeme.fiyati+"", 269, 77 + ( index * 6));
  });

  doc.text(obj.dokuman || '', 10, 105);
  doc.text(obj.aciklama || '', 10, 139);

  if(obj.personel && obj.personelYedek){
    doc.setFontSize(12);
    doc.text(obj.personel || '',20,170)
    doc.setFontSize(8);
    doc.text(obj.personelKase || '',20,175)

    doc.setFontSize(12);
    doc.text(obj.personelYedek || '',90,170)
    doc.setFontSize(8);
    doc.text(obj.personelYedekKase || '',90,175)

    doc.setFontSize(12);
    doc.text(obj.kalite || '',160,170)
    doc.setFontSize(8);
    doc.text(obj.kaliteKase || '',160,175)

    doc.setFontSize(12);
    doc.text(obj.yonetici || '', 230, 170);
    doc.setFontSize(8);
    doc.text(obj.yoneticiKase || '', 230, 175);
  }else{

    if(obj.personel){
      doc.setFontSize(12);
      doc.text(obj.personel || '',40,170)
      doc.setFontSize(8);
      doc.text(obj.personelKase || '',40,175)
    }else if(obj.personelYedek){
      doc.setFontSize(12);
      doc.text(obj.personelYedek || '',40,170)
      doc.setFontSize(8);
      doc.text(obj.personelYedekKase || '',40,175)
    }

    doc.setFontSize(12);
    doc.text(obj.kalite || '',140,170)
    doc.setFontSize(8);
    doc.text(obj.kaliteKase || '',140,175)

    doc.setFontSize(12);
    doc.text(obj.yonetici || '', 210, 170);
    doc.setFontSize(8);
    doc.text(obj.yoneticiKase || '', 210, 175);

  }
  

  
  if(com){
    com.print(doc);
  }else{
    doc.save(obj.kontrolNo || '');
  }
}
